1a62c8567390b5db293ddf348d4f16357ebc9674:
query FlxAppPrefs {
  flxAppPrefs {
    ...FlxAppPrefsFields
  }
}

fragment FlxAppPrefsFields on FlxAppPrefs {
  order
  hidden
  pinned
  forceWeb
  tabs
  cardOrder
  cardHidden
  push {
    event
    on
  }
  events {
    id
    title
    source
    default
    on
  }
  updated
}

1eacda91aa4cc35d78858bd1216b721f00317704:
query FlxAppDashboard {
  flxAppDashboard {
    cards {
      id
      title
      value
      sub
      icon
      tone
      url
      open
      order
    }
    lists {
      id
      title
      icon
      url
      open
      order
      items {
        title
        sub
        meta
        url
      }
    }
  }
}

522afbeb70b132491258fc307b12fa464f70e26a:
mutation FlxAppPrefsUpdate($input: FlxAppPrefsUpdateInput!) {
  flxAppPrefsUpdate(input: $input) {
    prefs {
      ...FlxAppPrefsFields
    }
    errors {
      code
      message
      field
    }
  }
}

fragment FlxAppPrefsFields on FlxAppPrefs {
  order
  hidden
  pinned
  forceWeb
  tabs
  cardOrder
  cardHidden
  push {
    event
    on
  }
  events {
    id
    title
    source
    default
    on
  }
  updated
}

74959c1f5581dbb6bbff6bc34c10bd2f42777d0b:
query FlxAppSync($since: Int) {
  flxAppSync(since: $since) {
    counts {
      key
      value
    }
    hashes {
      me
      config
      manifest
    }
    events {
      event
      title
      body
      target
      params
      at
    }
    serverTime
  }
}

7609ec865712b962f6777d969a7d24945a7b0bcd:
mutation FlxAppSessionCreate($input: FlxAppSessionCreateInput!) {
  flxAppSessionCreate(input: $input) {
    url
    expiresIn
    errors {
      code
      message
      field
    }
  }
}

be768903018c97df98f3c8a1d6561d546d8d03a9:
query FlxAppManifest($ifHash: String) {
  flxAppManifest(ifHash: $ifHash) {
    schema
    hash
    notModified
    platform
    modules {
      id
      document
    }
  }
}

cba8508c6de751e14f96be2f2c48765115575862:
query FlxAppMe {
  flxAppMe {
    user {
      databaseId
      login
      name
      email
      avatar
      roles {
        id
        name
      }
      locale
      isAdmin
      profileUrl
    }
    site {
      name
      url
      adminUrl
      restUrl
      icon
      locale
      timezone
    }
    auth {
      kind
      client
      scope
      expires
    }
    menu {
      id
      slug
      title
      url
      icon
      iconUrl
      badge
      items {
        slug
        title
        url
        badge
      }
    }
    modules {
      id
      title
      menu
      api
      icon
      version
      order
      url
      hasManifest
      extra
    }
    counts {
      key
      value
    }
    bottom
    webSession
    caps {
      key
      granted
    }
    versions {
      slug
      version
    }
    layout {
      pins
      groups {
        id
        label
        collapsed
        items
      }
    }
    hashes {
      me
      config
      manifest
    }
  }
}

